const ANIM={
 moraes:{idle:[3,0],walk:[5,3],light:[4],heavy:[2],block:[3],cast:[1],hurt:[5],jump:[3],sit:[5]},
 kabo:{idle:[3,0],walk:[0,3],light:[1],heavy:[6],block:[4],cast:[2],hurt:[5],jump:[7],sit:[0]},
 kbene:{idle:[5,3],walk:[0,1],light:[4],heavy:[2],block:[3],cast:[4],hurt:[0],jump:[1],sit:[0]},
 subaz:{idle:[3,0],walk:[0,3],light:[2],heavy:[4],block:[5],cast:[1],hurt:[0],jump:[3],sit:[0]},
 reymond:{idle:[0,1],walk:[1,3],light:[2],heavy:[6],block:[4],cast:[7],hurt:[3],jump:[5],sit:[4]},
 dpaul:{idle:[3],walk:[3,4],light:[2],heavy:[5],block:[4],cast:[0],hurt:[4],jump:[1],sit:[4]},
 jota:{idle:[1,0],walk:[3,1],light:[2],heavy:[5],block:[4],cast:[0],hurt:[4],jump:[1],sit:[4]},
 jorge:{idle:[0,2],walk:[2,0],light:[4],heavy:[6],block:[5],cast:[1],castMap:{horse:[3],padaria:[3]},hurt:[5],jump:[2],sit:[1],dash:[6],upper:[3]},
 hered:{idle:[0],walk:[0,4],light:[9],heavy:[7],block:[4],cast:[1],castMap:{troco:[2],bar:[6]},hurt:[3],jump:[8],sit:[4],slide:[3],upper:[2]},
 berri:{idle:[0],walk:[0,7],light:[8],heavy:[6],block:[9],cast:[1],castMap:{jamais:[1],nunca:[9],jamaisnov:[5]},hurt:[3],jump:[7],sit:[1],slide:[4],upper:[4],poses:{shield:[10],finger:[5],power:[11]}},
 vald:{idle:[0],walk:[0,7],light:[8],heavy:[6],block:[0],cast:[1],castMap:{bone:[4],chuveiro:[1],atrasado:[5]},hurt:[0],jump:[7],sit:[0],dash:[2],upper:[3]},
};
const FRAME_FLIP={kbene:{4:-1}};                       // quadros desenhados virados para a esquerda
const SPR_REF={moraes:[3,80],kabo:[0,80],kbene:[5,82],subaz:[3,80],reymond:[0,80],dpaul:[3,88],jota:[0,88],jorge:[0,86],hered:[0,88],vald:[0,86],berri:[0,88]}; // [quadro de referência, altura do corpo em px no jogo]
const SPR={};
function obterCorteSprite(idPersonagem,img,frameAtual){
 const L=SPR_RECTS[idPersonagem],r=L[((frameAtual%L.length)+L.length)%L.length];
 return{sx:r[0],sy:r[1],sw:r[2],sh:r[3],ax:r[4],fy:r[5],bh:r[6]};
}
function preloadSprites(){
 ORDER.forEach(id=>{
  if(!SPRITE_SRC[id])return;
  const img=new Image();
  img.onload=()=>{
   const mk=col=>{const c=document.createElement('canvas');c.width=img.width;c.height=img.height;const g=c.getContext('2d');g.drawImage(img,0,0);g.globalCompositeOperation='source-in';g.fillStyle=col;g.fillRect(0,0,c.width,c.height);return c};
   const ref=SPR_REF[id],cut=obterCorteSprite(id,img,ref[0]);
   SPR[id]={img,white:mk('#fff'),tint:{},mk,s:ref[1]/cut.bh,ready:true};
  };
  img.src=SPRITE_SRC[id];
 });
}
function tinted(id,col){const S=SPR[id];return S.tint[col]||(S.tint[col]=S.mk(col))}
function sprFrame(p,t,T){
 const pick=(L,rate,off)=>L[Math.floor(rate*1+off)%L.length];
 let L,k=0;
 if(p.ko||p.pose==='held'||p.pose==='held2'||p.pose==='self'||p.pose==='zap'||p.pose==='burn')L=T.hurt;
 else if(p.pose==='slide'&&T.slide)L=T.slide;
 else if(p.pose==='upper'&&T.upper)L=T.upper;
 else if(p.pose&&T.poses&&T.poses[p.pose])L=T.poses[p.pose];
 else if(p.pose==='sit'||p.pose==='phone')L=T.sit;
 else if(p.cast)L=(T.castMap&&T.castMap[p.cast.d.run])||T.cast;
 else if(p.atk)L=p.atk.k==='h'?T.heavy:T.light;
 else if(p.blk)L=T.block;
 else if(p.stun>0)L=T.hurt;
 else if(p.y>3)L=T.jump;
 else if(p.dash&&T.dash)L=T.dash;
 else if(p.st==='walk')return T.walk[Math.floor((p.walk||0)*5)%T.walk.length];
 else return T.idle[Math.floor(t*2.6+(p.i||0)*.7)%T.idle.length];
 return L[Math.floor(t*6)%L.length];
}
function drawSpriteFighter(c2,p,t,gy,sc){
 if(p.away||p.hide)return;
 const S=SPR[p.ch],T=ANIM[p.ch],fi=sprFrame(p,t,T),cut=obterCorteSprite(p.ch,S.img,fi);
 const k=S.s*sc,dw=cut.sw*k,dh=cut.bh*k,fy=cut.fy*k,ax=cut.ax*k;
 const flip=(FRAME_FLIP[p.ch]&&FRAME_FLIP[p.ch][fi])||1;
 const px=Math.round(p.x),py=Math.round(gy-p.y);
 const bx=(p.ch==='dpaul'?1+.07*(p.stacks||0):1)*(p.ch==='kabo'&&p.thin>0?.86:1);
 // sombra no chão
 c2.fillStyle='rgba(0,0,0,.35)';const sw=Math.max(8,dw*.3*bx-Math.min(6,p.y/9));c2.fillRect(px-sw,gy+1,sw*2,3);
 let lean=0,lunge=0;
 if(p.atk&&!p.ko){const a=p.atk,ext=a.t<a.hitT?(-.3+1.3*a.t/a.hitT):Math.max(0,1-(a.t-a.hitT)/(a.dur-a.hitT));lunge=ext*6;lean=ext*.09}
 else if(p.stun>0&&!p.ko)lean=-.1;
 const shake=(p.stun>0&&!p.ko&&(p.pose==='zap'||p.pose==='self'))?Math.sin(t*50)*1.5:0;
 const breathe=(!p.atk&&!p.ko&&p.y<3)?Math.sin(t*5+(p.i||0))*.012:0;
 const draw=(img,alpha,ox,oy)=>{
  c2.save();c2.globalAlpha=(c2.globalAlpha||1)*alpha;c2.imageSmoothingEnabled=true;
  c2.translate(px+shake,py);c2.scale(p.face*flip*bx,1);
  if(p.ko){c2.translate(0,-dw*.3);c2.rotate(-Math.PI/2)}
  c2.translate(lunge,0);c2.rotate(lean);c2.scale(1,1+breathe);
  c2.drawImage(img,cut.sx,cut.sy,cut.sw,cut.sh,-ax+(ox||0),-fy+(oy||0),dw,cut.sh*k);
  c2.restore();
 };
 const ga=c2.globalAlpha;
 // aura do modo secreto: contorno colorido + chamas atrás
 if(p.secOn){
  const col=CH[p.ch].sec.aura;
  c2.save();c2.translate(px,py);c2.fillStyle=col;c2.globalAlpha=.3*ga;
  for(let q=-2;q<=2;q++){const h=dh*.5+Math.sin(t*9+q*1.7)*8;c2.fillRect(q*7-3,-h-12,6,h+12)}
  c2.restore();
  const tt=tinted(p.ch,col);for(const [ox,oy] of [[-2,0],[2,0],[0,-2],[0,2]])draw(tt,.75*ga,ox,oy);
 }
 c2.globalAlpha=ga;
 draw(S.img,1,0,0);
 if(p.flash>0)draw(S.white,.55*ga,0,0);
 c2.globalAlpha=ga;
 // escudos de defesa
 c2.save();c2.translate(px,py);c2.scale(p.face,1);
 const F=(x,y,w,h,col)=>{c2.fillStyle=col;c2.fillRect(x,-y-h,w,h)};
 if(p.blk){
  const bx0=dw*.28;
  if(p.ch==='subaz'){for(let q=0;q<3;q++){c2.save();c2.translate(bx0+6,-dh*.5);c2.rotate((q-1)*.25);c2.fillStyle='#f6f6f2';c2.fillRect(-4,-9,9,16);c2.fillStyle='#999';c2.fillRect(-2,-6,5,1);c2.fillRect(-2,-3,5,1);c2.fillStyle='#c33';c2.fillRect(-2,0,5,1);c2.restore()}}
  else if(p.ch==='dpaul'){F(bx0,dh*.38,16,4,'#7a4a2a');F(bx0,dh*.38,3,20,'#7a4a2a');F(bx0+1,dh*.2,2,12,'#4a2a18');F(bx0+13,dh*.2,2,12,'#4a2a18')}
  else if(p.ch==='moraes'){for(let q=0;q<5;q++){const h=18+Math.sin(t*14+q*2)*7;F(bx0+q*3,dh*.22,4,h,q%2?'#ffcf3a':'#ff6a1a')}}
  else if(p.ch==='kabo'){for(let q=0;q<8;q++){F(bx0+(q%3)*4,dh*.3+((q*5)%16),4,4,q%2?'#ff5fa8':'#ff9ad0');F(bx0+1+(q%3)*4,dh*.26,1,5,'#2f9a4a')}}
 }
 c2.restore();
 if(p.blk&&p.ch==='kbene'&&p.cl<=0){
  const g0=c2.globalAlpha;c2.globalAlpha=.5*g0;
  c2.save();c2.translate(px+p.face*14,py);c2.scale(p.face*(FRAME_FLIP.kbene[T.block[0]]||1),1);
  c2.drawImage(S.img,cut.sx,cut.sy,cut.sw,cut.sh,-ax,-fy,dw,cut.sh*k);c2.restore();c2.globalAlpha=g0;
 }
 c2.imageSmoothingEnabled=false;
 // efeitos de estado
 c2.save();c2.translate(px,py);
 if(p.burn>0&&!p.ko){for(let q=0;q<5;q++){const h=10+Math.sin(t*17+q*2.3)*5;c2.fillStyle=p.burnCol;c2.fillRect(-dw*.22+q*dw*.11,-dh*.55-h,4,h);c2.fillStyle='#fff0a0';c2.fillRect(-dw*.22+q*dw*.11+1,-dh*.55-h+2,1,h-4)}}
 if(p.pose==='phone'&&!p.ko){const bl=Math.sin(t*9)>0;c2.fillStyle='#111';c2.fillRect(p.face*10-3,-dh*.5-6,7,12);c2.fillStyle=bl?'#6fd0ff':'#d86fff';c2.fillRect(p.face*10-2,-dh*.5-5,5,10)}
 if(p.fire&&!p.ko){for(let q=0;q<2;q++){const h=9+Math.sin(t*20+q*2)*4,bq=p.face*(dw*.30+q*8);c2.fillStyle='#ff6fc8';c2.fillRect(bq-3,-dh*.5-h,6,h);c2.fillStyle='#ffd0ee';c2.fillRect(bq-1,-dh*.5-h+3,2,Math.max(2,h-3))}}
 if(p.wet>0&&!p.ko){for(let q=0;q<5;q++){const yy=((t*40+q*13)%30);c2.fillStyle=q%2?'#ffcf4a':'#fff1b0';c2.fillRect(-dw*.2+q*dw*.1,-dh*.7+yy,2,3)}}
 if(p.paint>0&&!p.ko){c2.fillStyle='#ffe21a';c2.fillRect(-4,-dh*.62,5,4);c2.fillRect(2,-dh*.5,6,3);c2.fillRect(-7,-dh*.4,4,5)}
 if(p.spk>0&&!p.ko){c2.fillStyle='#c8f5ff';for(let q=0;q<5;q++)c2.fillRect(rndT(t*3,q,30)-15,-rndT(t*3,q+7,dh),2,4)}
 if(p.pose==='zap'){c2.fillStyle='#ffe84a';for(let q=0;q<7;q++)c2.fillRect(rndT(t,q,40)-20,-rndT(t,q+9,dh),2,6)}
 if(p.stun>.6&&!p.ko&&!p.ns){for(let q=0;q<3;q++){const an=t*6+q*2.1;c2.fillStyle='#ffe84a';c2.fillRect(Math.cos(an)*9-1,-dh-3+Math.sin(an)*2,3,3)}}
 if(p.rage>0){c2.fillStyle='#ff3030';c2.fillRect(-6,-dh+2,4,2);c2.fillRect(3,-dh+2,4,2)}
 c2.restore();
}

/* ============ RENDER ============ */
const cv=document.getElementById('cv'),ctx=cv.getContext('2d');
const $=id=>document.getElementById(id);
const shadeCache={};
function shade(hex,f){const k=hex+f;if(shadeCache[k])return shadeCache[k];const n=parseInt(hex.slice(1),16);const r=((n>>16)&255)*f|0,g=((n>>8)&255)*f|0,b=(n&255)*f|0;return shadeCache[k]='rgb('+r+','+g+','+b+')'}

const BG=document.createElement('canvas');BG.width=W;BG.height=H;
