 F(178,110,54,10,'#444b57');F(184,124,20,26,'#14161a');F(210,124,18,6,'#c33');F(210,134,18,6,'#3c3');
 F(190,150,10,12,'#f2f2f2');F(178,160,54,10,'#14161a');
 // purificador
 F(250,96,26,80,'#eef0f2');F(254,104,18,14,'#7fb8d6');F(256,130,14,6,'#bbb');
 // ar-condicionado
 F(320,12,120,34,'#f2f4f6');F(324,30,112,12,'#d3d8dd');for(let x=326;x<434;x+=6)F(x,32,2,8,'#b6bcc2');
 // lixeiras
 F(364,140,34,36,'#c0262d');F(360,136,42,6,'#9a1a20');F(374,150,14,14,'#f5f5f5');F(378,154,6,6,'#c0262d');
 F(410,140,34,36,'#2a5db8');F(406,136,42,6,'#1e458a');
 // rodapé e piso
 F(0,172,W,6,'#7c858d');
 F(0,178,W,92,'#9ea5ab');
 for(let y=178;y<H;y+=(y-170)/3|0||14){F(0,y,W,1,'#8a9197')}
 for(let x=-240;x<W+240;x+=40){g.fillStyle='#8a9197';g.beginPath();g.moveTo(x+(x-W/2)*.12*0+0,178);g.lineTo(W/2+(x-W/2)*2.2,H);g.lineTo(W/2+(x-W/2)*2.2+1,H);g.lineTo(x+1,178);g.fill()}
 F(0,H-6,W,6,'#7c858d');
