   const sx=V.x-34,sy=Math.max(20,GY-V.y-128);F(V.x-1,0,2,sy,'#555');F(sx,sy,68,24,'#1a0600');F(sx+2,sy+2,64,20,Math.sin(t*14)>-.6?'#ff9a2a':'#7a3a10');
